Check(concrete.Argument?.CollectionType?.Contains("IReadOnlyList")==true&&concrete.Children.Single().Kind=="Shoot"&&doc.CanEditChildren(concrete.Id),"A concrete initializer retains its formal read-only list Add contract and source collection syntax");
