var spreadSource=source.Replace(arrayText,"[new Shoot(20,count:4,fixedAngle:0,coolDown:100),..StudioEntryShared]").Replace("private _ StudioCollectionEntry=", "static readonly CycleBehavior[] StudioEntryShared=new CycleBehavior[]{new Shoot(20,count:2,fixedAngle:0,coolDown:100)}; private _ StudioCollectionEntry=");var spreadDoc=new BehaviorDocument(spreadSource,adapter,sourceFile:file);var spreadList=spreadDoc.Entities.Single().Root.Descendants().First(n=>n.Argument?.Name=="primary");var spread=spreadList.Children.Single(n=>n.Kind=="Spread");spreadDoc.MoveNode(spread.Id,-1,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(spreadDoc.Find(spreadList.Id).Children.First().Id==spread.Id&&spreadDoc.Source.Contains("..StudioEntryShared"),"Spread inputs inside an Add collection retain exact source bindings and identities during reorder");var spreadCopy=spreadDoc.DuplicateNode(spread.Id,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(spreadCopy!=spread.Id&&spreadDoc.Find(spreadCopy).Kind=="Spread","Entry-owned spread duplication retains the actual shared expression with an independent editor identity");spreadDoc.Undo();
var generated=new BehaviorDocument(spreadSource.Replace("[new Shoot(20,count:4,fixedAngle:0,coolDown:100),..StudioEntryShared]","StudioEntryShared"),adapter,sourceFile:file);var generatedList=generated.Entities.Single().Root.Descendants().First(n=>n.Argument?.Name=="primary");Check(generatedList.ArgumentRequiresSource&&!generated.CanEditChildren(generatedList.Id),"A referenced generated list retains its explicit source owner rather than receiving invented inline elements");
doc.MoveNode(array.Children[1].Id,-1,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(doc.Find(array.Id).Children.First().Id==array.Children[1].Id&&doc.Find(after.Id).Children.Single().Id==after.Children.Single().Id&&doc.Source.Contains("/* list note */"),"Element reorder preserves the paired key, scalar sibling, identities and internal comments");
var duplicated=doc.DuplicateNode(array.Children[0].Id,d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(doc.Find(array.Id).Children.Count==3&&duplicated!=array.Children[0].Id,"List child duplication allocates a fresh native identity without copying the entry");doc.Undo();
doc.DeleteNodes(doc.Find(array.Id).Children.Select(n=>n.Id),d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(doc.Find(array.Id).Children.Count==0&&doc.Expression(doc.Find(array.Id)).StartsWith("new CycleBehavior[]"),"Deleting every array input retains a valid empty native array and its slot identity");
doc.AddChild(array.Id,"new Shoot(20,count:6,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(doc.Find(array.Id).Children.Single().Parameters.Any(p=>p.Name=="count"&&p.Expression=="6"),"An empty array Add input supports native refill");
