doc.LockedNodes.Add(after.Id);doc.AddChild(array.Id,"new Shoot(20,count:8,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,"Cave Pirate Brawler"));Check(doc.Find(after.Id).Children.Single().Id==after.Children.Single().Id,"An unrelated locked scalar child input permits collection editing");doc.LockedNodes.Clear();
doc.LockedNodes.Add(array.Id);Reject(()=>doc.AddChild(array.Id,"new Shoot(20)"),"A collection input lock protects its native list contents");doc.LockedNodes.Clear();
var accepted=doc.Source;var acceptedIds=doc.Identities;Reject(()=>doc.AddChild(array.Id,"new global::TKR.WorldServer.logic.transitions.TimedTransition(100,\"loop\")"),"An incompatible collection child rejects before source mutation");Check(doc.Source==accepted&&doc.Identities.SequenceEqual(acceptedIds),"Rejected list edits preserve accepted source and identities");
var output=Path.GetFullPath(".artifacts/collection-entry");Directory.CreateDirectory(output);var project=new StudioProject{SourceFile=file,Source=doc.Source,EntityId="Cave Pirate Brawler",Identities=doc.Identities,Player=new(Invulnerable:true),Seed=7};var path=Path.Combine(output,"collection-entry.rbs");BehaviorDocument.Save(path,project);var saved=BehaviorDocument.Load(path);var reopened=new BehaviorDocument(saved.Source,adapter,saved.Identities,file);Check(reopened.Identities.SequenceEqual(doc.Identities),"Collection entry and element identities persist through save/reopen");
