var createdSource=doc.Source;var createdIds=doc.Identities;Check(doc.Undo()&&doc.Source==source&&doc.Redo()&&doc.Source==createdSource&&doc.Identities.SequenceEqual(createdIds),"One creation Undo/Redo retains the full list and fresh entry descendants");
