Reject(()=>doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","9"}},new Dictionary<string,string>{{"primary","[new global::TKR.WorldServer.logic.transitions.TimedTransition(100,\"loop\")]"}}),"Incompatible complete-list creation rejects atomically");string invalidMessage="";try{doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","9"}},new Dictionary<string,string>{{"primary","[new global::TKR.WorldServer.logic.transitions.TimedTransition(100,\"loop\")]"}});}catch(ArgumentException error){invalidMessage=error.Message;}Check(invalidMessage.Contains("TimedTransition")&&invalidMessage.Contains("CycleBehavior"),"Invalid collection creation reports the actual native type conversion error: "+invalidMessage);
