Reject(()=>doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","9"}},new Dictionary<string,string>{{"primary","System.Array.Empty<CycleBehavior>()"}}),"Generated complete-list creation retains its source boundary");Check(doc.Source==createdSource,"Rejected generated-list creation leaves the accepted source untouched");
